using Content.Shared.Guidebook;
using Robust.Shared.GameStates;

namespace Content.Shared.Doors.Components;

/// <summary>
/// Companion component to <see cref="DoorComponent"/> that handles firelock-specific behavior, including
/// auto-closing on depressurization, air/fire alarm interactions, and preventing normal door functions when
/// retaining pressure..
/// </summary>
[RegisterComponent, NetworkedComponent, AutoGenerateComponentState]
public sealed partial class FirelockComponent : Component
{
    #region Settings

    /// <summary>
    /// Pry time modifier to be used when the firelock is currently closed due to fire or pressure.
    /// </summary>
    [DataField]
    public float LockedPryTimeModifier = 1.5f;

    /// <summary>
    /// Maximum pressure difference before the firelock will refuse to open, in kPa.
    /// </summary>
    [DataField, GuidebookData]
    public float PressureThreshold = 20;

    /// <summary>
    /// Maximum temperature difference before the firelock will refuse to open, in k.
    /// </summary>
    [DataField, GuidebookData]
    public float TemperatureThreshold = 230;
    // this used to check for hot-spots, but because accessing that data is a a mess this now just checks
    // temperature. This does mean a cold room will trigger hot-air pop-ups

    /// <summary>
    /// If true, and if this door has an <see cref="AtmosAlarmableComponent"/>, then it will only auto-close if the
    /// alarm is set to danger.
    /// </summary>
    [DataField]
    public bool AlarmAutoClose = true;

    /// <summary>
    /// The cooldown duration before a firelock can automatically close due to a hazardous environment after it has
    /// been pried open. Measured in seconds.
    /// </summary>
    [DataField]
    public TimeSpan EmergencyCloseCooldownDuration = TimeSpan.FromSeconds(2);

    #endregion

    #region Set by system

    /// <summary>
    /// When the firelock will be allowed to automatically close again due to a hazardous environment.
    /// </summary>
    [DataField]
    public TimeSpan? EmergencyCloseCooldown;

    /// <summary>
    /// Whether the firelock can open, or is locked due to its environment.
    /// </summary>
    public bool IsLocked => Pressure || Temperature;

    /// <summary>
    /// Whether the firelock is holding back a hazardous pressure.
    /// </summary>
    [DataField, AutoNetworkedField]
    public bool Pressure;

    /// <summary>
    /// Whether the firelock is holding back extreme temperatures.
    /// </summary>
    [DataField, AutoNetworkedField]
    public bool Temperature;

    /// <summary>
    /// Whether the airlock is powered.
    /// </summary>
    [DataField, AutoNetworkedField]
    public bool Powered;

    #endregion

    #region Client animation

    /// <summary>
    /// The sprite state used to animate the airlock frame when the airlock opens.
    /// </summary>
    [DataField]
    public string? OpeningLightSpriteState = "opening_unlit";

    /// <summary>
    /// The sprite state used to animate the airlock frame when the airlock closes.
    /// </summary>
    [DataField]
    public string? ClosingLightSpriteState = "closing_unlit";

    /// <summary>
    /// Whether or not the maintenance panel on this door should be animated.
    /// </summary>
    [DataField]
    public bool AnimatePanel = true;

    /// <summary>
    /// The sprite state used to animate the airlock panel when the airlock opens.
    /// </summary>
    [DataField]
    public string? OpeningPanelSpriteState = "panel_opening";

    /// <summary>
    /// The sprite state used to draw when the door is closed, but the panel is open.
    /// </summary>
    [DataField]
    public string? OpenPanelSpriteState = "panel_open";

    /// <summary>
    /// The sprite state used to animate the airlock panel when the airlock closes.
    /// </summary>
    [DataField]
    public string? ClosingPanelSpriteState = "panel_closing";

    /// <summary>
    /// The sprite state used for the closed airlock lights.
    /// </summary>
    [DataField]
    public string? WarningLightSpriteState = "closed_unlit";

    /// <summary>
    /// The sprite state used for the 'access denied' lights animation.
    /// </summary>
    [DataField]
    public string? DenySpriteState = "deny_unlit";

    #endregion
}
using Content.Server.Atmos.Components;
using Content.Server.Explosion.EntitySystems;
using Content.Shared.Atmos;
using JetBrains.Annotations;
using Robust.Shared.Map.Components;

namespace Content.Server.Atmos.EntitySystems
{
    [UsedImplicitly]
    public sealed partial class AirtightSystem : EntitySystem
    {
        [Dependency] private SharedTransformSystem _transform = default!;
        [Dependency] private AtmosphereSystem _atmosphereSystem = default!;
        [Dependency] private ExplosionSystem _explosionSystem = default!;
        [Dependency] private SharedMapSystem _mapSystem = default!;

        public override void Initialize()
        {
            SubscribeLocalEvent<AirtightComponent, ComponentInit>(OnAirtightInit);
            SubscribeLocalEvent<AirtightComponent, ComponentShutdown>(OnAirtightShutdown);
            SubscribeLocalEvent<AirtightComponent, AnchorStateChangedEvent>(OnAirtightPositionChanged);
            SubscribeLocalEvent<AirtightComponent, ReAnchorEvent>(OnAirtightReAnchor);
            SubscribeLocalEvent<AirtightComponent, MoveEvent>(OnAirtightMoved);
        }

        private void OnAirtightInit(Entity<AirtightComponent> airtight, ref ComponentInit args)
        {
            // If this entity blocks air in all directions (e.g. full tile walls, doors, and windows)
            // we can skip some expensive logic.
            if (airtight.Comp.InitialAirBlockedDirection == (int)AtmosDirection.All)
            {
                airtight.Comp.CurrentAirBlockedDirection = airtight.Comp.InitialAirBlockedDirection;
                UpdatePosition(airtight);
                return;
            }

            // Otherwise we need to determine its current blocked air directions based on rotation
            // and check if it's still airtight.
            var xform = Transform(airtight);
            airtight.Comp.CurrentAirBlockedDirection =
                (int) Rotate((AtmosDirection) airtight.Comp.InitialAirBlockedDirection, xform.LocalRotation);
            UpdatePosition(airtight, xform);
            var airtightEv = new AirtightChanged(airtight, airtight, false, default);
            RaiseLocalEvent(airtight, ref airtightEv, true);
        }

        private void OnAirtightShutdown(Entity<AirtightComponent> airtight, ref ComponentShutdown args)
        {
            var xform = Transform(airtight);

            // If the grid is deleting no point updating atmos.
            if (xform.GridUid != null && LifeStage(xform.GridUid.Value) <= EntityLifeStage.MapInitialized)
                SetAirblocked(airtight, false, xform);
        }

        private void OnAirtightPositionChanged(EntityUid uid, AirtightComponent airtight, ref AnchorStateChangedEvent args)
        {
            var xform = args.Transform;

            if (!TryComp(xform.GridUid, out MapGridComponent? grid))
                return;

            var gridId = xform.GridUid;
            var coords = xform.Coordinates;
            var tilePos = _mapSystem.TileIndicesFor(gridId.Value, grid, coords);

            // Update and invalidate new position.
            airtight.LastPosition = (gridId.Value, tilePos);
            InvalidatePosition(gridId.Value, tilePos);

            var airtightEv = new AirtightChanged(uid, airtight, false, (gridId.Value, tilePos));
            RaiseLocalEvent(uid, ref airtightEv, true);
        }

        private void OnAirtightReAnchor(EntityUid uid, AirtightComponent airtight, ref ReAnchorEvent args)
        {
            foreach (var gridId in new[] { args.OldGrid, args.Grid })
            {
                // Update and invalidate new position.
                airtight.LastPosition = (gridId, args.TilePos);
                InvalidatePosition(gridId, args.TilePos);

                var airtightEv = new AirtightChanged(uid, airtight, false, (gridId, args.TilePos));
                RaiseLocalEvent(uid, ref airtightEv, true);
            }
        }

        private void OnAirtightMoved(Entity<AirtightComponent> ent, ref MoveEvent ev)
        {
            var (owner, airtight) = ent;
            airtight.CurrentAirBlockedDirection = (int) Rotate((AtmosDirection)airtight.InitialAirBlockedDirection, ev.NewRotation);
            var pos = airtight.LastPosition;
            UpdatePosition(ent, ev.Component);
            var airtightEv = new AirtightChanged(owner, airtight, false, pos);
            RaiseLocalEvent(owner, ref airtightEv, true);
        }

        public void SetAirblocked(Entity<AirtightComponent> airtight, bool airblocked, TransformComponent? xform = null)
        {
            if (airtight.Comp.AirBlocked == airblocked)
                return;

            if (!Resolve(airtight, ref xform))
                return;

            var pos = airtight.Comp.LastPosition;
            airtight.Comp.AirBlocked = airblocked;
            if (!airblocked)
                UpdatePosition(airtight, xform);
            var airtightEv = new AirtightChanged(airtight, airtight, true, pos);
            RaiseLocalEvent(airtight, ref airtightEv, true);
        }

        public void UpdatePosition(Entity<AirtightComponent> ent, TransformComponent? xform = null)
        {
            var (owner, airtight) = ent;
            if (!Resolve(owner, ref xform))
                return;

            if (!xform.Anchored || !TryComp(xform.GridUid, out MapGridComponent? grid))
                return;

            var indices = _transform.GetGridTilePositionOrDefault((ent, xform), grid);
            airtight.LastPosition = (xform.GridUid.Value, indices);
            InvalidatePosition((xform.GridUid.Value, grid), indices);
        }

        public void InvalidatePosition(Entity<MapGridComponent?> grid, Vector2i pos)
        {
            _explosionSystem.UpdateAirtightMap(grid, pos, grid);
            _atmosphereSystem.InvalidateTile(grid.Owner, pos);
        }

        private AtmosDirection Rotate(AtmosDirection myDirection, Angle myAngle)
        {
            var newAirBlockedDirs = AtmosDirection.Invalid;

            if (myAngle == Angle.Zero)
                return myDirection;

            // TODO ATMOS MULTIZ: When we make multiZ atmos, special case this.
            for (var i = 0; i < Atmospherics.Directions; i++)
            {
                var direction = (AtmosDirection) (1 << i);
                if (!myDirection.IsFlagSet(direction))
                    continue;
                var angle = direction.ToAngle();
                angle += myAngle;
                newAirBlockedDirs |= angle.ToAtmosDirectionCardinal();
            }

            return newAirBlockedDirs;
        }
    }

    /// <summary>
    /// Raised upon the airtight status being changed via anchoring, movement, etc.
    /// </summary>
    /// <param name="Entity"></param>
    /// <param name="Airtight"></param>
    /// <param name="AirBlockedChanged">Whether the <see cref="AirtightComponent.AirBlocked"/> changed</param>
    /// <param name="Position"></param>
    [ByRefEvent]
    public readonly record struct AirtightChanged(EntityUid Entity, AirtightComponent Airtight, bool AirBlockedChanged, (EntityUid Grid, Vector2i Tile) Position);
}

